add_task(async function test_setState() {
  subview.setState();
  let userName = "";
  let focusedInput = realName;

  if ("@mozilla.org/userinfo;1" in Cc) {
    userName = Cc["@mozilla.org/userinfo;1"].getService(
      Ci.nsIUserInfo
    ).fullname;
    focusedInput = userName ? email : focusedInput;
  }

  Assert.equal(
    focusedInput,
    subview.ownerDocument.activeElement,
    "Correct input should be focused"
  );

  Assert.equal(realName.value, userName, "Name input value should be correct");
  Assert.equal(email.value, "", "Email input value should be empty");
  Assert.equal(
    email.ariaInvalid,
    "false",
    "Empty email input should not show an error on initial render"
  );
  Assert.ok(
    BrowserTestUtils.isHidden(subview.querySelector("#emailWarning")),
    "Empty email input should not show a warning icon on initial render"
  );
});

add_task(async function test_resetState() {
  realName.value = "Name";
  email.value = "email@test.email";

  const invalidUpdatedInput = BrowserTestUtils.waitForEvent(
    subview,
    "config-updated"
  );

  subview.resetState();

  const inValid = await invalidUpdatedInput;
  let userName = "";

  if ("@mozilla.org/userinfo;1" in Cc) {
    userName = Cc["@mozilla.org/userinfo;1"].getService(
      Ci.nsIUserInfo
    ).fullname;
  }

  Assert.equal(realName.value, userName, "Name input value should be correct");
  Assert.equal(email.value, "", "Email input value should be empty");
  Assert.equal(
    email.ariaInvalid,
    "false",
    "Empty email input should not show an error after reset"
  );
  Assert.ok(
    BrowserTestUtils.isHidden(subview.querySelector("#emailWarning")),
    "Empty email input should not show a warning icon after reset"
  );

  Assert.ok(
    !inValid.detail.completed,
    "Event should indicate the form is not complete"
  );
});

add_task(async function test_checkValidEmailForm() {
  subview.setState();
  EventUtils.synthesizeMouseAtCenter(email, {}, subview.documentGlobal);
  // Windows 64 bit test builds need focus to be called on the input for
  // tests to pass.
  email.focus();

  let invalidUpdatedInput = BrowserTestUtils.waitForEvent(
    subview,
    "config-updated",
    false,
    () => email.value === "test"
  );
  EventUtils.sendString("test", browser.contentWindow);
  let invalidUpdatedEvent = await invalidUpdatedInput;

  Assert.ok(
    !invalidUpdatedEvent.detail.completed,
    "Event should indicate the form is not complete"
  );
  Assert.ok(
    BrowserTestUtils.isHidden(manualConfigButton),
    "Manual config button should be hidden"
  );
  Assert.equal(
    email.ariaInvalid,
    "true",
    "Email should have aria-invalid set to true"
  );

  realName.value = "";
  email.value = "";

  invalidUpdatedInput = BrowserTestUtils.waitForEvent(
    subview,
    "config-updated",
    false,
    () => email.value === "test@test.com"
  );
  EventUtils.sendString("test@test.com", browser.contentWindow);
  invalidUpdatedEvent = await invalidUpdatedInput;

  Assert.ok(
    !invalidUpdatedEvent.detail.completed,
    "Event should indicate the form is not complete"
  );
  Assert.ok(
    BrowserTestUtils.isHidden(manualConfigButton),
    "Manual config button should be hidden"
  );
  Assert.equal(
    email.ariaInvalid,
    "false",
    "Email should have aria-invalid set to false"
  );
  Assert.equal(
    realName.ariaInvalid,
    "false",
    "Untouched name should not have aria-invalid set to true"
  );

  realName.value = "Test Name";
  const validUpdatedInput = BrowserTestUtils.waitForEvent(
    subview,
    "config-updated"
  );
  subview.checkValidEmailForm();

  const validUpdatedEvent = await validUpdatedInput;
  Assert.ok(
    validUpdatedEvent.detail.completed,
    "Event should indicate the form is complete"
  );
  Assert.ok(
    BrowserTestUtils.isVisible(manualConfigButton),
    "Manual config button should be visible"
  );
  Assert.equal(
    realName.ariaInvalid,
    "false",
    "Name should have aria-invalid set to false"
  );

  subview.resetState();
});

add_task(function test_captureState() {
  realName.value = "Test";
  email.value = "test@test.com";
  subview.checkValidEmailForm();

  Assert.deepEqual(
    subview.captureState(),
    {
      realName: "Test",
      email: "test@test.com",
    },
    "Should get the entered data in the captured state"
  );
  subview.resetState();
});

add_task(function test_disabled() {
  Assert.ok(!realName.disabled, "Name input should start enabled");
  Assert.ok(!email.disabled, "Email input should start enabled");
  Assert.ok(
    !manualConfigButton.disabled,
    "Manual config button should start enabled"
  );
  Assert.ok(
    !thundermailButton.disabled,
    "Thundermail button should start enabled"
  );

  subview.disabled = true;

  Assert.ok(realName.disabled, "Name input should be disabled");
  Assert.ok(email.disabled, "Email input should be disabled");
  Assert.ok(
    manualConfigButton.disabled,
    "Manual config button should be disabled"
  );
  Assert.ok(
    thundermailButton.disabled,
    "Thundermail button should be disabled"
  );

  subview.disabled = false;

  Assert.ok(!realName.disabled, "Name input should be enabled again");
  Assert.ok(!email.disabled, "Email input should be enabled again");
  Assert.ok(
    !manualConfigButton.disabled,
    "Manual config button should be enabled again"
  );
  Assert.ok(
    !thundermailButton.disabled,
    "Thundermail button should be enabled again"
  );
});

